//! YAML generators for benchmarking and testing.
//!
//! These patterns are the **end-to-end** side of YAML benchmarking: they feed
//! `dev bench yq`, `benches/yq_comparison.rs` and `benches/yq_select.rs`, which
//! exercise the query and streaming paths. `benches/yaml_bench.rs` covers the
//! index-**build** path separately, over its own inline fixtures.
//!
//! # Feature coverage
//!
//! Every construct `src/yaml/mod.rs` lists as supported is generated by at
//! least one pattern, and `tests/yaml_bench_suite_coverage.rs` fails the build
//! if that stops being true. The realistic patterns (`users`, `config`, …) are
//! block-style; the feature-focused patterns below carry the rest:
//!
//! | feature                        | pattern         |
//! |--------------------------------|-----------------|
//! | flow mapping / sequence        | `flow`          |
//! | anchors, aliases, merge keys `<<:` | `anchors`   |
//! | block scalars `\|` `>` + chomping | `block-scalars` |
//! | explicit keys `? ` / `: `      | `explicit-keys` |
//! | multi-document `---` / `...`   | `multi-doc`     |
//!
//! # Deliberately absent
//!
//! These would make every generated file diverge from `yq`, so the coverage
//! test asserts they are **not** generated. Fixing any of them should flip that
//! assertion, not pass silently:
//!
//! - **Tags (`!!str`, `!custom`)** — rejected outright in block context; a
//!   documented non-support in `src/yaml/mod.rs`.
//!
//! # Shape guards, not features (#516)
//!
//! `empty-items` and `half-empty-items` do not carry a *construct* absent
//! elsewhere — a childless bare-dash item parses the same as any other
//! sequence item. They exist because #337 found that exact shape quadratic
//! while every generator only ever emitted `- ` items with content nested
//! underneath, so the regression (and its later, incidental fix) had zero
//! benchmark coverage. Per `docs/guides/benchmarking.md` rule 7: a benchmark
//! cannot measure a shape it does not generate.
//!
//! # Why this file exists in this shape (#327)
//!
//! Until #327 none of the features above were generated at all, so "every
//! end-to-end benchmark is neutral" carried no information about them — the
//! same blind spot that let the quadratic sequence-iteration bug in #106
//! survive a full benchmark run.

use rand::{RngExt, SeedableRng};
use rand_chacha::ChaCha8Rng;

pub use crate::yaml_pattern_registry::{PatternScale, YamlPattern, ALL_PATTERNS};

/// Generate YAML of approximately target_size bytes
pub fn generate_yaml(target_size: usize, pattern: YamlPattern, seed: Option<u64>) -> String {
    match pattern {
        YamlPattern::Comprehensive => generate_comprehensive(target_size, seed),
        YamlPattern::Users => generate_users(target_size, seed),
        YamlPattern::Nested => generate_nested(target_size, seed),
        YamlPattern::Sequences => generate_sequences(target_size, seed),
        YamlPattern::Mixed => generate_mixed(target_size, seed),
        YamlPattern::Strings => generate_strings(target_size, seed),
        YamlPattern::Numbers => generate_numbers(target_size, seed),
        YamlPattern::Config => generate_config(target_size, seed),
        YamlPattern::Unicode => generate_unicode(target_size, seed),
        YamlPattern::Pathological => generate_pathological(target_size, seed),
        YamlPattern::Navigation => generate_navigation(target_size, seed),
        YamlPattern::Flow => generate_flow(target_size, seed),
        YamlPattern::Anchors => generate_anchors(target_size, seed),
        YamlPattern::BlockScalars => generate_block_scalars(target_size, seed),
        YamlPattern::ExplicitKeys => generate_explicit_keys(target_size, seed),
        YamlPattern::MultiDoc => generate_multidoc(target_size, seed),
        YamlPattern::EmptyItems => generate_empty_items(target_size),
        YamlPattern::HalfEmptyItems => generate_half_empty_items(target_size),
    }
}

/// Comprehensive YAML with various features
fn generate_comprehensive(target_size: usize, seed: Option<u64>) -> String {
    let mut rng = seed.map(ChaCha8Rng::seed_from_u64);
    let mut yaml = String::with_capacity(target_size);

    // Metadata section
    yaml.push_str("# Comprehensive YAML test file\n");
    yaml.push_str("metadata:\n");
    yaml.push_str("  version: \"1.0\"\n");
    yaml.push_str("  generated: true\n");
    yaml.push_str("  features:\n");
    yaml.push_str("    - mappings\n");
    yaml.push_str("    - sequences\n");
    yaml.push_str("    - strings\n");
    yaml.push_str("    - numbers\n");
    yaml.push_str("    - nested\n");
    yaml.push('\n');

    // Calculate feature sizes
    let remaining = target_size.saturating_sub(yaml.len());
    let feature_size = remaining / 6;

    // Simple values section
    yaml.push_str("simple_values:\n");
    add_simple_values(&mut yaml, feature_size, &mut rng, 2);
    yaml.push('\n');

    // Strings section
    yaml.push_str("strings:\n");
    add_string_values(&mut yaml, feature_size, &mut rng, 2);
    yaml.push('\n');

    // Numbers section
    yaml.push_str("numbers:\n");
    add_number_values(&mut yaml, feature_size, &mut rng, 2);
    yaml.push('\n');

    // Nested section. The depth below is a shape choice, not a parser limit —
    // see `generate_nested` for what actually bounds nesting.
    yaml.push_str("nested:\n");
    add_nested_mapping(&mut yaml, feature_size, &mut rng, 2, 3);
    yaml.push('\n');

    // Data records
    yaml.push_str("data:\n");
    add_user_records(&mut yaml, feature_size, &mut rng, 2);
    yaml.push('\n');

    // Sequences
    yaml.push_str("sequences:\n");
    add_sequence_values(&mut yaml, feature_size, &mut rng, 2);

    yaml
}

/// Generate user/person records
fn generate_users(target_size: usize, seed: Option<u64>) -> String {
    let mut rng = seed.map(ChaCha8Rng::seed_from_u64);
    let mut yaml = String::with_capacity(target_size);

    yaml.push_str("# User records\n");
    yaml.push_str("users:\n");

    add_user_records(&mut yaml, target_size.saturating_sub(20), &mut rng, 2);

    yaml
}

/// Generate deeply nested structures
fn generate_nested(target_size: usize, seed: Option<u64>) -> String {
    let mut rng = seed.map(ChaCha8Rng::seed_from_u64);
    let mut yaml = String::with_capacity(target_size);

    yaml.push_str("# Deeply nested structure\n");
    yaml.push_str("root:\n");

    // A shape choice, not a parser limit. The "BP tree i16 overflow" this
    // comment used to claim does not exist: the `i16` values in `src/trees/bp.rs`
    // are per-block min/total excess, unrelated to document depth. Block nesting
    // is iterative (`indent_stack` in `src/yaml/parser.rs`), and the parser's
    // `MAX_NESTING_DEPTH` of 128 bounds only recursively-parsed constructs —
    // flow collections and inline `- - x` chains. Depth 40 block nesting parses
    // and matches yq; `tests/deep_nesting_valid_tests.rs` pins depth 100.
    //
    // The value stays at 6 so this pattern's bytes — and every benchmark number
    // recorded against them — remain comparable across the change (#327).
    let max_depth = 6;
    add_nested_mapping(
        &mut yaml,
        target_size.saturating_sub(30),
        &mut rng,
        2,
        max_depth,
    );

    yaml
}

